def f(I):
    h=len(I); w=len(I[0])
    pts=[(i,j,I[i][j]) for i in range(h) for j in range(w) if I[i][j]!=0]
    from collections import Counter
    c=Counter(v for _,_,v in pts)
    accent=min(c,key=c.get)
    r0=min(i for i,_,_ in pts); r1=max(i for i,_,_ in pts)
    c0=min(j for _,j,_ in pts); c1=max(j for _,j,_ in pts)
    ph=r1-r0+1; pw=c1-c0+1
    p=(min(ph,pw)//2)-1
    o=[r[:] for r in I]
    for i in range(r0-p,r1+p+1):
        for j in range(c0-p,c1+p+1):
            if i<r0 or i>r1 or j<c0 or j>c1:
                o[i][j]=accent
    return o
